export const chatsListInfiniteQueryKey = (
  options?: Options<ChatsListData>,
): QueryKey<Options<ChatsListData>> =>
  createQueryKey("chatsList", options, true);

/**
 * List chats in a workspace
 */
export const chatsListInfiniteOptions = (options?: Options<ChatsListData>) => {
  const opts = infiniteQueryOptions<
    ChatsListResponse,
    ChatsListError,
    InfiniteData<ChatsListResponse>,
    QueryKey<Options<ChatsListData>>,
    | number
    | null
    | Pick<
        QueryKey<Options<ChatsListData>>[0],
        "body" | "headers" | "path" | "query"
      >
  >(
    // @ts-ignore
    {
      queryFn: async ({ pageParam, queryKey, signal }) => {
        // @ts-ignore
        const page: Pick<
          QueryKey<Options<ChatsListData>>[0],
          "body" | "headers" | "path" | "query"
        > =
          typeof pageParam === "object"
            ? pageParam
            : {
                query: {
                  offset: pageParam,
                },
              };
        const params = createInfiniteParams(queryKey, page);
        const { data } = await chatsList({
          ...options,
          ...params,
          signal,
          throwOnError: true,
        });
        return data;
      },
      queryKey: chatsListInfiniteQueryKey(options),
    },
  );
  return opts as Omit<typeof opts, "initialData">;
};

